    /**
     * Tests getting all InspectionResults.
     *
     * @return    Collection
     */
    public List<InspectionResult> testGetAll() throws Throwable {
    LOGGER.info( "InspectionResultTest:testGetAll() - Retrieving Collection of InspectionResults:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all InspectionResult : " );
    List<InspectionResult> collection  = null;

    try {
        // call the static get method on the InspectionResultService
        collection = service.getAllInspectionResult();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            InspectionResult currEntity  = null;
            Iterator<InspectionResult> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInspectionResultId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

